variables.support_zone:
{% set t1 = state_attr('climate.1p_chodba','current_temperature') %}
{% set t2 = state_attr('climate.prizemi_chodba_zachod','current_temperature') %}
{% set ok1 = is_state('binary_sensor.heating_valve_1p_chodba_alive','on')
   and is_state('binary_sensor.zona_1p_chodba_okno_otevrene','off')
   and is_state('input_boolean.schedule_enable_1p_chodba','on')
   and is_state('input_boolean.1p_chodba_manual_override','off')
   and (states('sensor.zona_1p_chodba_demand') | float(0)) < (states('input_number.kotel_min_zone_demand_pct') | float(70))
   and states('climate.1p_chodba') not in ['unknown','unavailable','']
   and is_number(t1) and (t1|float) < 24.0 %}
{% set ok2 = is_state('binary_sensor.heating_valve_prizemi_chodba_zachod_alive','on')
   and is_state('binary_sensor.zona_prizemi_chodba_zachod_okno_otevrene','off')
   and is_state('input_boolean.schedule_enable_prizemi_chodba_zachod','on')
   and is_state('input_boolean.prizemi_chodba_zachod_manual_override','off')
   and (states('sensor.zona_prizemi_chodba_zachod_demand') | float(0)) < (states('input_number.kotel_min_zone_demand_pct') | float(70))
   and states('climate.prizemi_chodba_zachod') not in ['unknown','unavailable','']
   and is_number(t2) and (t2|float) < 24.0 %}
{% if ok1 and ok2 %}
  {{ 'climate.1p_chodba' if (t1|float) <= (t2|float) else 'climate.prizemi_chodba_zachod' }}
{% elif ok1 %}
  climate.1p_chodba
{% elif ok2 %}
  climate.prizemi_chodba_zachod
{% else %}
  none
{% endif %}

actions.wait_template:
{% set z = support_zone | trim %}
{{ (states('sensor.kotel_aktivni_zony_pocet') | int(0)) >= 2
   or not is_state('input_boolean.topny_system_enable','on')
   or is_state('input_boolean.heating_service_mode','on')
   or states('input_select.topeni_hydraulicka_podpurna_zona') != z }}

variables.support_confirmed:
{% set z = states('input_select.topeni_hydraulicka_podpurna_zona') %}
{% set zid = z.split('.')[1] if '.' in z else '' %}
{{ z in ['climate.1p_chodba','climate.prizemi_chodba_zachod']
   and (states('sensor.kotel_aktivni_zony_pocet') | int(0)) >= 2
   and is_state('binary_sensor.' ~ zid ~ '_potrebne_teplo','on')
   and (states('sensor.' ~ zid ~ '_pozadavek_na_vytapeni_pi') | float(0)) >= 5
   and is_number(state_attr(z,'temperature'))
   and ((state_attr(z,'temperature') | float(0)) - 29) | abs <= 0.1 }}

